#!/usr/bin/env python3
"""Turns components/vellum_core/web/upload.html into C++ source.

Run after editing the page:
  python3 tools/embed_page.py
The host tests check that the generated file matches the page.
"""
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
page = (root / "components/vellum_core/web/upload.html").read_text(encoding="utf-8")
if ')page"' in page:
    raise SystemExit('the page contains the raw-string delimiter )page"')
out = root / "components/vellum_core/src/upload_page.cpp"
out.write_text(
    "// Generated by tools/embed_page.py from web/upload.html. Do not edit.\n"
    '#include "vellum/upload_page.h"\n\n'
    "namespace vellum {\n\n"
    'const char kUploadPage[] = R"page(' + page + ')page";\n\n'
    "const unsigned kUploadPageSize = sizeof(kUploadPage) - 1;\n\n"
    "}  // namespace vellum\n",
    encoding="utf-8",
)
print(f"wrote {out.relative_to(root)} ({len(page.encode())} bytes)")
